solution:
use xiom.io;
use xiom.math;
enum CharacterClass {
  Warrior,
  Mage,
  Rogue,
}

type Hero = {
  name: Str;
  class: CharacterClass;
  strength: Int;
  intelligence: Int;
  agility: Int;
  hit_points: Int;
  mana_points: Int;
  damage: Int;
  armor: Str;
  weapon: Str;
}

fn roll_stat() -> Int {
  let d1 = math.random_range(1, 7);
  let d2 = math.random_range(1, 7);
  let d3 = math.random_range(1, 7);
  d1 + d2 + d3
}

fn class_name(cls: CharacterClass) -> Str {
  match cls {
    CharacterClass.Warrior => "Warrior",
    CharacterClass.Mage => "Mage",
    CharacterClass.Rogue => "Rogue",
  }
}

fn calculate_hp(cls: CharacterClass, str: Int) -> Int {
  let base = match cls {
    CharacterClass.Warrior => 20,
    CharacterClass.Mage => 10,
    CharacterClass.Rogue => 14,
  };
  base + str * 2
}

fn calculate_mp(cls: CharacterClass, intel: Int) -> Int {
  let base = match cls {
    CharacterClass.Warrior => 4,
    CharacterClass.Mage => 25,
    CharacterClass.Rogue => 10,
  };
  base + intel * 3
}

fn calculate_damage(cls: CharacterClass, str: Int, intel: Int, agi: Int) -> Int {
  match cls {
    CharacterClass.Warrior => 5 + str * 2,
    CharacterClass.Mage => 3 + intel * 3,
    CharacterClass.Rogue => 4 + agi * 2 + str,
  }
}

fn equip_character(cls: CharacterClass) -> (Str, Str) {
  match cls {
    CharacterClass.Warrior => ("Plate Armor", "Longsword"),
    CharacterClass.Mage => ("Arcane Robes", "Crystal Staff"),
    CharacterClass.Rogue => ("Leather Armor", "Twin Daggers"),
  }
}

fn create_hero(name: Str, cls: CharacterClass) -> Hero {
  let str = roll_stat();
  let intel = roll_stat();
  let agi = roll_stat();
  let eq = equip_character(cls);

  Hero{
    name: name,
    class: cls,
    strength: str,
    intelligence: intel,
    agility: agi,
    hit_points: calculate_hp(cls, str),
    mana_points: calculate_mp(cls, intel),
    damage: calculate_damage(cls, str, intel, agi),
    armor: eq.0,
    weapon: eq.1,
  }
}

fn display_hero(h: &Hero) {
  io.println("CHARACTER SHEET");
  io.println(h.name.to_str());
  io.println(class_name(h.class));
  io.println(h.strength.to_str());
  io.println(h.intelligence.to_str());
  io.println(h.agility.to_str());
  io.println(h.hit_points.to_str());
  io.println(h.mana_points.to_str());
  io.println(h.damage.to_str());
  io.println(h.armor.to_str());
  io.println(h.weapon.to_str());
}

fn main() -> Int {
  let hero = create_hero("Thorn", CharacterClass.Warrior);
  display_hero(&hero);
  return 0;
}
